namespace Dentara.Domain.Scheduling;

using Dentara.Domain.Common;

/// <summary>
/// A single bookable time slot, generated by the publication worker when a
/// BookingWindow transitions to Open.
///
/// IMPORTANT: a PublishedSession is NOT a reservation. It's a marker that
/// "this dentist is expected to be available at this time, and bookings
/// are now accepted". The actual capacity reservation happens in the Booking
/// module via Appointments + ResourceAllocations under a SQL Server transaction
/// (per ADR-003).
///
/// At booking time, the system RE-CHECKS the dentist's WorkSchedule and
/// ScheduleExceptions for the session's time range — the PublishedSession
/// alone is not a guarantee of availability.
/// </summary>
public sealed class PublishedSession : Entity
{
    public Guid BookingWindowId { get; private set; }

    public Guid DentistId { get; private set; }

    public DateTimeOffset StartAtUtc { get; private set; }

    public DateTimeOffset EndAtUtc { get; private set; }

    /// <summary>
    /// Logical key for idempotent publication. Set to a deterministic hash of
    /// (BookingWindowId, DentistId, StartAtUtc). UNIQUE constraint prevents
    /// duplicate session generation when the worker re-runs.
    /// </summary>
    public string IdempotencyKey { get; private set; } = string.Empty;

    /// <summary>
    /// True if this session has been booked at least once. Used to hide
    /// long-tail published sessions that have no demand (cosmetic only).
    /// </summary>
    public bool HasEverBeenBooked { get; private set; }

    /// <summary>
    /// When this session was published (i.e. when the worker created it).
    /// </summary>
    public DateTimeOffset PublishedAtUtc { get; private set; }

    private PublishedSession() { } // EF Core

    public static PublishedSession Create(
        Guid bookingWindowId,
        Guid dentistId,
        DateTimeOffset startAtUtc,
        DateTimeOffset endAtUtc,
        IClock clock)
    {
        if (bookingWindowId == Guid.Empty)
            throw new ArgumentException("BookingWindowId is required.", nameof(bookingWindowId));
        if (dentistId == Guid.Empty)
            throw new ArgumentException("DentistId is required.", nameof(dentistId));
        if (startAtUtc.Offset != TimeSpan.Zero)
            throw new ArgumentException("StartAt must be UTC.", nameof(startAtUtc));
        if (endAtUtc.Offset != TimeSpan.Zero)
            throw new ArgumentException("EndAt must be UTC.", nameof(endAtUtc));
        if (startAtUtc >= endAtUtc)
            throw new ArgumentException("StartAt must be before EndAt.");

        return new PublishedSession
        {
            BookingWindowId = bookingWindowId,
            DentistId = dentistId,
            StartAtUtc = startAtUtc,
            EndAtUtc = endAtUtc,
            IdempotencyKey = BuildIdempotencyKey(bookingWindowId, dentistId, startAtUtc),
            PublishedAtUtc = clock.UtcNow,
            CreatedAtUtc = clock.UtcNow
        };
    }

    public TimeRange ToTimeRange() => new(StartAtUtc, EndAtUtc);

    public void MarkBooked(IClock clock)
    {
        HasEverBeenBooked = true;
        Touch(clock.UtcNow);
    }

    /// <summary>
    /// Builds a deterministic idempotency key from the natural key.
    /// Used both for the IdempotencyKey column and for deduplication
    /// during publication re-runs.
    /// </summary>
    public static string BuildIdempotencyKey(Guid bookingWindowId, Guid dentistId, DateTimeOffset startAtUtc)
    {
        return $"{bookingWindowId:N}|{dentistId:N}|{startAtUtc:O}";
    }
}
